export class DriveError extends Error {
    status;
    code;
    retryAfterMs;
    constructor(message, status, code = 'drive_error', retryAfterMs) {
        super(message);
        this.status = status;
        this.code = code;
        this.retryAfterMs = retryAfterMs;
        this.name = 'DriveError';
    }
}
